// @ts-expect-error `.open-next/worker.js` is generated by the Cloudflare adapter at build time.
import { default as nextHandler } from "./.open-next/worker.js";
import { rebuildLatestRecommendationSnapshots } from "./lib/meta-beta/aggregation";
import type { D1DatabaseBinding } from "./lib/meta-beta/auth";
import { GLOBAL_META_REGION } from "./lib/meta-beta/global-ingest";

interface WorkerEnv {
  DB?: D1DatabaseBinding;
}

interface ScheduledEventLike {
  cron: string;
  scheduledTime: number;
}

interface ExecutionContextLike {
  waitUntil(promise: Promise<unknown>): void;
}

async function cleanupOperationalData(db: D1DatabaseBinding, now = Date.now()): Promise<void> {
  const cutoff = new Date(now - 14 * 24 * 60 * 60 * 1000).toISOString().slice(0, 10);
  await db.batch([
    db.prepare("DELETE FROM ai_usage_daily WHERE usage_date < ?").bind(cutoff),
    db.prepare("DELETE FROM ai_response_cache WHERE expires_at <= ?").bind(Math.floor(now / 1000)),
  ]);
}

const worker = {
  fetch: nextHandler.fetch,

  async scheduled(
    event: ScheduledEventLike,
    env: WorkerEnv,
    context: ExecutionContextLike,
  ): Promise<void> {
    if (!env.DB) {
      console.warn("Scheduled ranked-meta task skipped because the DB binding is unavailable");
      return;
    }

    const scheduledTime = Number.isFinite(event.scheduledTime) ? event.scheduledTime : Date.now();

    if (event.cron === "17 * * * *") {
      // Global ranked match ingestion is provider-driven. The previous tracked-player
      // collector is intentionally disabled because this product does not build its
      // statistics from individual opt-in accounts.
      return;
    }

    if (event.cron === "0 19 * * *") {
      const rebuild = rebuildLatestRecommendationSnapshots(env.DB, GLOBAL_META_REGION, scheduledTime);
      context.waitUntil(cleanupOperationalData(env.DB, scheduledTime));
      const result = await rebuild;
      console.log("Global ranked meta recommendation snapshot rebuilt", result);
    }
  },
};

export default worker;

// Re-export OpenNext durable objects when the generated worker provides them.
// @ts-expect-error `.open-next/worker.js` is generated by the Cloudflare adapter at build time.
export { DOQueueHandler, DOShardedTagCache } from "./.open-next/worker.js";
